import csv
import json
import math
import os

from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
SUB_DIR = "/app/submissions"
SOLUTION_PATH = os.path.join(SUB_DIR, "solution.csv")


def load_data():
    with open(os.path.join(DATA_DIR, "config.json")) as f:
        cfg = json.load(f)

    bases = {}
    with open(os.path.join(DATA_DIR, "bases.csv")) as f:
        for row in csv.DictReader(f):
            b = row["base_id"]
            bases[b] = {
                "open_cost": float(row["open_cost"]),
                "sortie_cap": float(row["daily_sortie_capacity"]),
                "batt_slots": int(row["battery_slots"]),
                "pilot_hours": float(row["pilot_shift_hours"]),
            }

    zones = {}
    with open(os.path.join(DATA_DIR, "demand_zones.csv")) as f:
        for row in csv.DictReader(f):
            z = row["zone_id"]
            zones[z] = {
                "packages": int(row["packages"]),
                "medical": int(row["medical_priority"]),
                "msr": float(row["minimum_service_rate"]),
            }

    arcs = {}
    with open(os.path.join(DATA_DIR, "base_zone_arcs.csv")) as f:
        for row in csv.DictReader(f):
            z = row["zone_id"]
            b = row["base_id"]
            arcs[(z, b)] = {
                "km": float(row["round_trip_km"]),
                "minutes": float(row["flight_minutes"]),
                "payload": int(row["max_payload_packages"]),
                "cost": float(row["cost_per_package"]),
            }
    return cfg, bases, zones, arcs


def max_unmet_for(zones, z, tol):
    d = zones[z]["packages"]
    msr = zones[z]["msr"]
    return max(0, int(math.floor((1.0 - msr) * d + tol)))


def main():
    os.makedirs(SUB_DIR, exist_ok=True)
    cfg, bases, zones, arcs = load_data()

    tol = float(cfg.get("feasibility_tolerance", 1e-5))
    lease_cost = float(cfg["battery_lease_cost"])
    unserved_pen = float(cfg["unserved_penalty_per_package"])

    time_limit = 300.0
    env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env_limit is not None:
        try:
            time_limit = min(time_limit, float(env_limit))
        except ValueError:
            pass

    model = Model("drone_base_assignment")
    model.setParam("gaprel", 0.0005)
    model.setParam("limits/time", time_limit)
    model.setMinimize()

    y = {}
    for b in bases:
        y[b] = model.addVar(name=f"y_{b}", vtype="B", lb=0.0, ub=1.0, obj=bases[b]["open_cost"])

    K = {}
    for b in bases:
        K[b] = model.addVar(name=f"K_{b}", vtype="I", lb=0.0, ub=float(bases[b]["batt_slots"]), obj=lease_cost)

    x = {}
    for (z, b), a in arcs.items():
        ub = float(zones[z]["packages"])
        x[(z, b)] = model.addVar(name=f"x_{z}_{b}", vtype="I", lb=0.0, ub=ub, obj=a["cost"])

    u = {}
    for z in zones:
        d = zones[z]["packages"]
        max_unmet = max_unmet_for(zones, z, tol)
        u[z] = model.addVar(name=f"u_{z}", vtype="I", lb=0.0, ub=float(max(max_unmet, 0)), obj=unserved_pen)

    obj_expr = quicksum(
        [bases[b]["open_cost"] * y[b] for b in bases]
        + [lease_cost * K[b] for b in bases]
        + [arcs[(z, b)]["cost"] * x[(z, b)] for (z, b) in arcs]
        + [unserved_pen * u[z] for z in zones]
    )
    model.setObjective(obj_expr, sense="minimize")

    # Demand balance
    for z in zones:
        d = zones[z]["packages"]
        cons = quicksum([x[(z, b)] for (zz, b) in arcs if zz == z]) + u[z]
        model.addCons(cons == d, name=f"balance_{z}")

    # Service rate
    for z in zones:
        max_unmet = max_unmet_for(zones, z, tol)
        model.addCons(u[z] <= max_unmet, name=f"service_{z}")

    # Base resource constraints
    for b in bases:
        arcs_b = [(z, a) for (z, bb), a in arcs.items() if bb == b]
        if not arcs_b:
            continue
        cons_sortie = quicksum([(1.0 / a["payload"]) * x[(z, b)] for z, a in arcs_b])
        model.addCons(cons_sortie <= bases[b]["sortie_cap"] * y[b], name=f"sortie_{b}")
        cons_hours = quicksum([(a["minutes"] / 60.0) * x[(z, b)] for z, a in arcs_b])
        model.addCons(cons_hours <= bases[b]["pilot_hours"] * y[b], name=f"hours_{b}")
        cons_batt = quicksum([x[(z, b)] for z, a in arcs_b])
        model.addCons(cons_batt <= K[b], name=f"batt_{b}")
        model.addCons(K[b] <= bases[b]["batt_slots"] * y[b], name=f"battcap_{b}")

    # Flow gating
    for (z, b) in arcs:
        model.addCons(x[(z, b)] <= zones[z]["packages"] * y[b], name=f"gate_{z}_{b}")

    try:
        model.optimize()
    except Exception as e:
        print(f"Solver error: {e}")

    status = model.getStatus()
    print("Status:", status)
    n_sols = model.getNSols()
    print("NSols:", n_sols)

    rows = []
    if n_sols > 0:
        sol = model.getBestSol()
        obj_val = model.getObjVal()
        print("Objective:", obj_val)

        y_val = {b: int(round(model.getVal(y[b]))) for b in bases}
        K_val = {b: int(round(model.getVal(K[b]))) for b in bases}
        x_val = {(z, b): int(round(model.getVal(x[(z, b)]))) for (z, b) in arcs}
        u_val = {z: int(round(model.getVal(u[z]))) for z in zones}

        ok = True
        for z in zones:
            served = sum(x_val[(z, b)] for (zz, b) in arcs if zz == z)
            if abs(served + u_val[z] - zones[z]["packages"]) > tol:
                ok = False
                print(f"FAIL balance {z}: served={served} unmet={u_val[z]} demand={zones[z]['packages']}")
            max_unmet = max_unmet_for(zones, z, tol)
            if u_val[z] > max_unmet + tol:
                ok = False
                print(f"FAIL service {z}: unmet={u_val[z]} max={max_unmet}")
        for b in bases:
            if y_val[b] == 0:
                tot = sum(x_val[(z, b)] for (zz, bb) in arcs if bb == b)
                if tot > tol:
                    ok = False
                    print(f"FAIL gating {b}: flow={tot} closed")
                if K_val[b] > tol:
                    ok = False
                    print(f"FAIL battcap {b}: K={K_val[b]} closed")
            else:
                tot = sum(x_val[(z, b)] for (zz, bb) in arcs if bb == b)
                if tot > bases[b]["batt_slots"] + tol:
                    ok = False
                    print(f"FAIL batt slots {b}: {tot}")
                if tot > K_val[b] + tol:
                    ok = False
                    print(f"FAIL batt cover {b}: flow={tot} K={K_val[b]}")
                sorties = sum((1.0 / arcs[(z, b)]["payload"]) * x_val[(z, b)] for (zz, bb) in arcs if bb == b)
                if sorties > bases[b]["sortie_cap"] + tol:
                    ok = False
                    print(f"FAIL sorties {b}: {sorties}")
                hours = sum((arcs[(z, b)]["minutes"] / 60.0) * x_val[(z, b)] for (zz, bb) in arcs if bb == b)
                if hours > bases[b]["pilot_hours"] + tol:
                    ok = False
                    print(f"FAIL hours {b}: {hours}")
        print("Validation:", "PASS" if ok else "FAIL")

        for b in sorted(bases):
            if y_val[b] == 1:
                rows.append(["open", b, "", "1"])
        for b in sorted(bases):
            if K_val[b] > 0:
                rows.append(["battery", b, "", str(K_val[b])])
        for (z, b) in sorted(x_val.keys()):
            if x_val[(z, b)] > 0:
                rows.append(["assignment", b, z, str(x_val[(z, b)])])
        for z in sorted(zones):
            if u_val[z] > 0:
                rows.append(["unmet", "", z, str(u_val[z])])
    else:
        print("No solution found; writing header only.")

    with open(SOLUTION_PATH, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["row_type", "base_id", "zone_id", "value"])
        for r in rows:
            w.writerow(r)
    print("Wrote", SOLUTION_PATH, "rows:", len(rows))

    model_md = """# Shared Drone Base Delivery Assignment — Mathematical Model

## Sets
- B: bases, Z: zones, A: feasible (z,b) arcs.

## Variables
- y_b ∈ {0,1} open
- K_b ∈ Z_+ ≤ batt_slots_b leased batteries
- x_{zb} ∈ Z_+ packages on arc
- u_z ∈ Z_+ unmet packages

## Objective (min)
Σ_b open_cost_b y_b + Σ_b 42 K_b + Σ_{(z,b)} c_{zb} x_{zb} + Σ_z 38 u_z

## Constraints
1. Σ_b x_{zb} + u_z = demand_z ∀z
2. u_z ≤ floor((1−msr_z)·demand_z + 1e-5) ∀z
3. Σ_z (1/p_{zb}) x_{zb} ≤ sortie_cap_b · y_b ∀b
4. Σ_z (t_{zb}/60) x_{zb} ≤ pilot_hours_b · y_b ∀b
5. Σ_z x_{zb} ≤ K_b ≤ batt_slots_b · y_b ∀b
6. x_{zb} ≤ demand_z · y_b ∀(z,b)
"""
    with open(os.path.join(SUB_DIR, "model.md"), "w") as f:
        f.write(model_md)

    model.free()


if __name__ == "__main__":
    main()
